script:
export const meta = {
  name: 'W913-预审与定稿',
  description: 'W913 剧情全图之用：方案稿之预审（三攻者：书之质、写书之流、执行与图）→ 纳防定稿（含圣经之补之环）⛔施',
  phases: [
    { title: '预审', detail: '三攻者' },
    { title: '定', detail: '纳防定稿' },
  ],
}
const S = '/tmp/claude-0/-home-user/fc87a25e-bbf0-5a31-be3f-8a53382aa0f0/scratchpad'
const WT = S + '/wt913'
const ENV = `
【境】施工之树：${WT}（detached 49dc2d27b＝今主枝）。方案稿：${WT}/设定/方案/W913.md（虫洞之择之三路设计、三判之分见 ${S}/../tasks/wozf8hxs2.output）。本 Run 唯写 ${WT}/设定/方案/W913.md（⛔改他档、⛔施码）。只读 /home/user/the-novel、${S}/wt911、${S}/wt912、${S}/wt914、${S}/wt480。⛔git 写。试於 /tmp 之副本，试毕删之。
二察之果：${S}/../tasks/w1yf5a4kx.output（剧情全图之质、写书之读、近章之迹）、${S}/../tasks/wcof4z7eu.output（圣经、总括、百科之鲜）。
作者 1120 之令（要）：剧情总图每章、每十章、全书——总括、所发、所推、所收之伏笔连其种章、新种、点睛与亮点、漏与可改；一眼看穿；每写一章必读；写完自动更新而连线；修改知改何处；构思以之定向；圣经、总括、百科随之与时俱进、与之相联、察其跟上否；严格用起、⛔一丝瑕疵；七大主义俱用；「刚开始做的时候就要做到100分」；「犯过的错不要再犯第二遍」。
律：W913 起之方案须有「兜底之隔：不改」一行（W911 新律·在「## 虫洞之择」）与「## 预审」一节（书预审之 Run 与逐条「- 险（环N｜取）：…｜防：…」·防须带锚〔工具/…、自测、格：、环N 改…、驳：由〕·⛔未防·末书「判：须改→已改 环N」或「判：可施」）——以 ${S}/wt911/工具/方案.py --验 W913 验之（wt911 之器为新律之本）。
既知之局：①480 段案之正另治（wt480：「一张嘴」已收於 478:137、温玉入 480 拍一）——W913 之回放与真用之验宜取之；②W913 改写书之路（章料、造章.js、封版 --前）→ 唯章界入主（480 封後·481 派前），先 ⚠ 一章；③W912（wt912）、W914（wt914）亦改 体系总图.py 与 法用册——并之序书於坑之检；④圣经诸档之落後（站况 E6—E8 书未写、七要角之档落 6—159 章、时间线末锚 305、canon roster 老头仍在、状态册末见章旧而型误、沈鸢知／不知自相违）须一次补之：立一环「圣经之补」——器只察只指（剧情全图 之圣经之鲜），补之文由总编辑亲裁或交剧情庭之裁（人事之疑如沈鸢之知须裁），⛔器改圣经之文。`
const ATK = { type: 'object', properties: { risks: { type: 'array', items: { type: 'object', properties: {
  risk: { type: 'string' }, ring: { type: 'string' }, evidence: { type: 'string' }, defense: { type: 'string' } }, required: ['risk', 'ring', 'evidence', 'defense'] } }, verdict: { type: 'string' } }, required: ['risks', 'verdict'] }
const PLAN = { type: 'object', properties: { file: { type: 'string' }, gist: { type: 'string' }, adopted: { type: 'number' }, rejected: { type: 'number' } }, required: ['file', 'gist'] }

phase('预审')
const atks = await parallel([
  ['书之质', '以书之质与读者之眼攻：任单之条会否诱执笔为收而硬插、伤节奏；「勿犯」之误判会否禁真好之笔；名约之误（名异致无着）；收之对账之 ⛔（482 起）会否逼记席虚书〔仍挂〕；精彩之最之源之偏；回放 471—480 之实例逐条验（含 480 段案之二病是否任单与派前之裁果能先见）。'],
  ['写书之流', '以写书之流与其回归攻：章料增读之量（≤900 字之实算）与秒、派令之序（自走.py:225）、造章.js 之令之改（N≥481 之条件、负测_造章令之 sha 基）、封版 --前 之秒与记席之治、段料之 KB、大审包之增；续跑之缓存；写者唯一（剧情全图.md 唯封版 --後 写；任单.json 之写者）；章界入主之序与 W912／W914 之并（同档同函）；479／480 正写时⛔扰。'],
  ['执行与图', '以执行主义与图攻：法用之证（起 481）可机验否、⛔可虚过否；体系总图之件之判（新件之谁跑谁读）、两图之约（W915 将立：剧情全图之式之变须钉）；图之自洽（连线两端之章俱在）；圣经之鲜之察之真（落後之条之判法：章差之算、误报）；「圣经之补」之环之可施（谁补、何时、如何裁沈鸢之知）；真用之验之迹（480／481 首章）。'],
].map(([k, p]) => () => agent(`${ENV}\n【汝之职】预审之攻者（只读）：${p}\n逐险书 risk、ring（环N 或「取」）、evidence（档:行或命令及其果）、defense；末书 verdict。`, { label: `预审:${k}`, phase: '预审', schema: ATK })))

phase('定')
const fin = await agent(`${ENV}
【汝之职】纳预审之防而定稿：逐险或纳（改其环、加其钉、改其序、增环）或驳（书由）；立「圣经之补」之环（照既知之局④）；於「## 虫洞之择」添「- 兜底之隔：不改」；「## 预审」一节照新律书：预审之 Run（本 Run：「预审:书之质」「预审:写书之流」「预审:执行与图」之三攻者——其 Run ID 由总编辑补书，汝先书「wf_待补」并於 gist 注明）与逐条「- 险（环N｜取）：…｜防：…」，末「判：须改→已改 环…」。跑 python3 ${S}/wt911/工具/方案.py --验 W913（以 cwd=${WT}·或照其用法指树）与今主枝之 方案.py --验 W913，至过（预审 Run 之验除外）。
预审：${JSON.stringify(atks.filter(Boolean))}
返 file、gist、adopted（纳几）、rejected（驳几）。`, { label: '定:W913', phase: '定', schema: PLAN })
return { atks, fin }
